-- Dolencias de biodescodificación basadas en Eric Corbera
-- Total: 30 dolencias completas
-- Ejecutar este script en Supabase SQL Editor

-- Limpiar tabla primero (opcional)
DELETE FROM dolencias WHERE categoria != 'SISTEMA_PLACEHOLDER';


-- Verificar inserción
SELECT COUNT(*) as total_dolencias FROM dolencias;
SELECT categoria, COUNT(*) as cantidad FROM dolencias GROUP BY categoria ORDER BY cantidad DESC;
